var timestamp = new Date(new Date().valueOf() - 30 * 24 * 60 * 60 * 1000).valueOf() * 1000000

var startLine1 = 0;
var startLine2 = 0;


const measure = 'OrderPerformance'
const product_id = 1
const data = {
    order_qty: [100000, 100000, 100000, 100000, 10000],
    order_state: ['planned',  'planned', 'planned', 'planned', 'planned'],
    planned_changeover_time: ['00:00:00', '00:30:00', '03:00:00', '00:00:50', '00:05:00'],
    planned_rate: [100, 100, 100, 100, 100],
    product_desc: ['Chicken Pizza', 'Chicken Pizza', 'Chicken Pizza', 'Chicken Pizza', 'Chicken Pizza'],
    setpoint_rate: [0, 0, 0, 0, 0],
    setpoint_rate_running: [100,100,100,100,100]
}

let categoryReasons = [
        {category_id:"Planned",reason_id:null,parent_reason_id:null}, 
        {category_id:"Planned",reason_id:"Break",parent_reason_id:"Break"},
        {category_id:"Planned",reason_id:"Meetings",parent_reason_id:"Meetings"},
        {category_id:"Planned",reason_id:"Preventative Maintenance",parent_reason_id:"Preventative Maintenance"},
        {category_id:"Planned",reason_id:"Holidays",parent_reason_id:"Holidays"},
        {category_id:"Planned",reason_id:"Shutdown",parent_reason_id:"Shutdown"},
        {category_id:"Unplanned",reason_id:null,parent_reason_id:null}, 
        {category_id:"Unplanned",reason_id:"Electrical Breakdown",parent_reason_id:"Electrical Breakdown"},
        {category_id:"Unplanned",reason_id:"Mechanical Breakdown",parent_reason_id:"Mechanical Breakdown"},
        {category_id:"Unplanned",reason_id:"Quality Issues",parent_reason_id:"Quality Issues"},
        {category_id:"Unplanned",reason_id:"Short Stop",parent_reason_id:"Short Stop"},
        {category_id:"Unplanned",reason_id:"Short Staffed",parent_reason_id:"Short Staffed"},
        {category_id:"Unplanned",reason_id:"No Orders",parent_reason_id:"No Orders"}
]

msg.payload = []
let orderCount = 0
let runningTimer = new Date(timestamp / 1000000).valueOf();
let lastMachineStateTime = null


for (var line of ['Site | Area | Line1', 'Site | Area | Line2']) {

    var hasFinalNext = 0
    let runningTimer = new Date(timestamp / 1000000).valueOf();

    if (lastMachineStateTime === null) {
        lastMachineStateTime = runningTimer
    }

    for (var j = 1; j<101; j++) {
        const i = j % 5
        orderCount++

        // Skip to 07:00 AM next business day if past 7pm
        let rt = new Date(runningTimer)
        if (rt.getHours() > 18 || rt.getDay() < 1 || rt.getDay() > 5) {
            rt.setHours(7)
            rt.setMinutes(7)
            rt.setSeconds(7)
            rt.setMilliseconds(7)
            const days = rt.getDay() < 5 ? 1 : (rt.getDay() == 5 ? 3 : 2)
            rt = new Date(rt.valueOf() + days * 24 * 60 * 60 * 1000)
            runningTimer = rt.getTime()
        }

        const orderDate = new Date(runningTimer).toISOString().substring(0,10)
        const scheduled_start_time = runningTimer
        const changeoverSeconds = Number(data.planned_changeover_time[i].split(":")[0]) * 60 * 60 + 
            Number(data.planned_changeover_time[i].split(":")[1]) * 60  + 
            Number(data.planned_changeover_time[i].split(":")[2])
        const runtimeSeconds = data.order_qty[i] * 1.0 / data.planned_rate[i] * 60
        const scheduled_end_time = runningTimer + (changeoverSeconds + runtimeSeconds) * 1000

        // Order Created
        let lineProtocol = `${measure},`
        lineProtocol += `order_id=${'1'+(orderCount + '').padStart(5, '0')}`
        lineProtocol += `,product_id=${product_id}`
        lineProtocol += ` ` // Gap for Fields
        lineProtocol += `order_date="${orderDate}",`
        lineProtocol += `order_qty=${data.order_qty[i]},`
        lineProtocol += `order_state="${data.order_state[i]}",`
        lineProtocol += `planned_changeover_time="${data.planned_changeover_time[i]}",`
        lineProtocol += `planned_rate=${data.planned_rate[i]},`
        lineProtocol += `product_desc="${data.product_desc[i]}",`
        lineProtocol += `production_line="${line}",`
        lineProtocol += `setpoint_rate=${data.setpoint_rate[i]}`
        msg.payload.push(lineProtocol + ` ${timestamp-2000}`)

        lineProtocol += `,scheduled_start_datetime=${scheduled_start_time},`
        lineProtocol += `scheduled_end_datetime=${scheduled_end_time}`
        lineProtocol += ` ${timestamp}`

        runningTimer = scheduled_end_time

        msg.payload.push(lineProtocol)

        // Order Planned/Released
        if ((scheduled_start_time - new Date().valueOf()) <= 14 * 24 * 60 * 60 * 1000  ) {
            // Is Order in the next two weeks?
            // Set to Ready
            lineProtocol = lineProtocol.replace("\"planned\"", "\"ready\"")
            lineProtocol = lineProtocol.replace(/\d+$/, timestamp + 2000)
            msg.payload.push(lineProtocol)
        }

        // Order Next
        // 4 - 8 hours before order starts
        let orderNextTime = scheduled_start_time - Math.round(Math.random() * 4 * 60 * 60 * 1000 + 4 * 60 * 60 * 1000)
        if (orderNextTime < new Date().valueOf() || hasFinalNext === 0) {
            if (orderNextTime > new Date().valueOf() && hasFinalNext === 0) {
                orderNextTime = new Date().valueOf()
            }
            lineProtocol = lineProtocol.replace("\"ready\"", "\"next\"")
            lineProtocol = lineProtocol.replace(/\d+$/, Math.round(orderNextTime*1000000))
            msg.payload.push(lineProtocol)
            hasFinalNext = 1
        }

        // Order Running
        const random1 = Math.round(Math.random() * 60 * 60 * 1000)
        let actual_start_datetime = scheduled_start_time + random1 - (0.5 * 60 * 60 * 1000)
        if (actual_start_datetime < new Date().valueOf()) {
            lineProtocol = lineProtocol.replace("\"next\"", "\"running\"")
            lineProtocol = lineProtocol.replace(`setpoint_rate=${data.setpoint_rate[i]}`, `setpoint_rate=${data.setpoint_rate_running[i]}`)
            lineProtocol = lineProtocol.replace(/ \d+$/, `,actual_start_datetime=${actual_start_datetime} ${Math.round(actual_start_datetime*1000000)}`)
            msg.payload.push(lineProtocol)
            hasFinalNext = 0
        }

        // Order Complete
        const random2 = Math.round(Math.random() * 60 * 60 * 1000 - 60 * 60 * 1000)
        let actual_end_datetime = scheduled_end_time + random2 -  random2 / 2
        if (actual_end_datetime < new Date().valueOf()) {
            lineProtocol = lineProtocol.replace("\"running\"", "\"complete\"")
            lineProtocol = lineProtocol.replace(`setpoint_rate=${data.setpoint_rate_running[i]}`, `setpoint_rate=${data.setpoint_rate[i]}`)
            lineProtocol = lineProtocol.replace(/ \d+$/, `,actual_end_datetime=${actual_end_datetime} ${Math.round(actual_end_datetime*1000000)}`)
            msg.payload.push(lineProtocol)
            hasFinalNext = 0
        }

        // Order Closed
        const random3 = Math.random() * 3 * 24 * 60 * 60 * 1000 
        let actual_close_datetime = actual_end_datetime + random3 // Up to 3 days after the order
        if (actual_close_datetime < new Date().valueOf()) {
            lineProtocol = lineProtocol.replace("\"complete\"", "\"closed\"")
            lineProtocol = lineProtocol.replace(/\d+$/, `${Math.round(actual_close_datetime*1000000)}`)
            msg.payload.push(lineProtocol)
            hasFinalNext = 0
        }

        if (lastMachineStateTime < new Date().valueOf()) {
            let range = Math.round(actual_close_datetime) - lastMachineStateTime
            let model = line.split(' | ')
            const downtimeEvents = Math.round(Math.random() * 10)
            const lineStatuss = ['stopped', 'execute', 'held', 'idle', 'complete']
            let times = []
            // Generate Timestamps
            for (var k = 0; k < (downtimeEvents * 2 + 6); k++) {
                times.push(Math.round(Math.random() * range))
            }

            times = times.sort((a,b) => { return a - b})


            // Generate Events
            for (var k = 0; k < (downtimeEvents * 2 + 6); k++ ) {
                lineProtocol = `Availability,Site=${model[0].replace(" ", "\ ")},Area=${model[1].replace(" ", "\ ")},Line=${model[2].replace(" ", "\ ")} `
                let performanceLine = `Performance,Site=${model[0].replace(" ", "\ ")},Area=${model[1].replace(" ", "\ ")},Line=${model[2].replace(" ", "\ ")} `
                let qualityLine = `Quality,Site=${model[0].replace(" ", "\ ")},Area=${model[1].replace(" ", "\ ")},Line=${model[2].replace(" ", "\ ")} `
                let status = null;

                if (k === 0 || k === (downtimeEvents * 2 + 5)) { status = 'stopped' }
                else if (k === 1 || k === (downtimeEvents * 2 + 4)) { status = 'idle' }
                else if ( k === 2) { status = 'execute' } 
                else if ( k === downtimeEvents * 2 + 3) { status = 'complete' }
                else {
                    if ((k - 2) % 2 === 0) { status = 'execute'} 
                    else { status = 'held'}
                }

                if (line.indexOf("Line1") >= 0) {
                    startLine1 = status === 'execute' ? 1 : 0;
                } else if (line.indexOf("Line2") >= 0) {
                    startLine2 = status === 'execute' ? 1 : 0;
                }

                lineProtocol += `status="${status}"`
                performanceLine += `status="${status}"`
                lineStatuss.forEach((s) => {
                    lineProtocol += `,${s}=${s === status ? 1 : 0}`
                    performanceLine += `,${s}=${s === status ? 1 : 0}.00`
                })

                performanceLine += `,planned_rate=${data.planned_rate[i]}`
                if (status === 'execute') {
                    performanceLine += `,actual_rate=${data.planned_rate[i]}`
                    qualityLine += ` Temp=${data.planned_rate[i]}`
                } else {
                    performanceLine += `,actual_rate=${0}`
                    qualityLine += ` Temp=0`
                }

                if (status === 'held') {
                    let categoryReasonIndex = Math.round(Math.random() * (categoryReasons.length - 1))
                    if (categoryReasonIndex.reason_id !== null) {
                        lineProtocol += `,category="${categoryReasons[categoryReasonIndex].category_id}"`
                        lineProtocol += `,reason="${categoryReasons[categoryReasonIndex].reason_id}"`
                        lineProtocol += `,parentReason="${categoryReasons[categoryReasonIndex].parent_reason_id}"`
                        lineProtocol += `,comment=""`
                    } else {
                        lineProtocol += `,category=""`
                        lineProtocol += `,reason=""`
                        lineProtocol += `,parentReason=""`
                        lineProtocol += `,comment=""`
                    }
                }

                if ((lastMachineStateTime + times[k]) > new Date().valueOf()) {
                    node.warn("Continuing as this event would be beyond now")
                    continue
                }

                lineProtocol += ` ${Math.round((lastMachineStateTime + times[k])*1000000)}`
                performanceLine += ` ${Math.round((lastMachineStateTime + times[k])*1000000)}`
                qualityLine += ` ${Math.round((lastMachineStateTime + times[k])*1000000)}`
                msg.payload.push(lineProtocol)
                msg.payload.push(performanceLine)
                msg.payload.push(qualityLine)
            }
            lastMachineStateTime = lastMachineStateTime + times[times.length -1]
        }
    }
}

